INSERT INTO SCHED_EXEC_LOG(
  FIRE_INSTANCE_ID, JOB_NAME, JOB_GROUP, TRIGGER_NAME, TRIGGER_GROUP,
  SCHEDULED_FIRE_TIME, ACTUAL_FIRE_TIME, STATUS
) VALUES (
  #{fireInstanceId}, #{jobName}, #{jobGroup}, #{triggerName}, #{triggerGroup},
  #{scheduledFireTime}, #{actualFireTime}, #{status}
)

mapper.update:
UPDATE SCHED_EXEC_LOG
   SET STATUS = #{status},
       FINISHED_AT = SYSTIMESTAMP,
       RUN_MILLIS = #{runMillis, jdbcType=NUMERIC},
       EXCEPTION_MESSAGE = #{exceptionMessage, jdbcType=VARCHAR}
 WHERE FIRE_INSTANCE_ID = #{fireInstanceId}
